const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Point([-76.009, 37.940]).buffer(3000); // Great Fox Island
    const year1_start = '1999-01-01';
    const year1_end = '1999-12-31';
    const year2_start = '2019-01-01';
    const year2_end = '2019-12-31';

    // Cloud masking function for Landsat 5/7 (Collection 1 SR)
    const cloudMaskL457 = function(image) {
      const qa = image.select('pixel_qa');
      // If the cloud bit (5) is set and the cloud confidence (7) is high
      // or the shadow bit (3) is set.
      const cloud = qa.bitwiseAnd(1 << 5).and(qa.bitwiseAnd(1 << 7)).or(qa.bitwiseAnd(1 << 3));
      // Remove edge pixels that don't have complete SR data.
      const mask2 = image.select('SR_B3').gt(1).unmask(0); // Check for valid SR data
      return image.updateMask(cloud.not()).updateMask(mask2);
    };

    // Cloud masking function for Landsat 8 (Collection 1 SR)
    const cloudMaskL8 = function(image) {
      const qa = image.select('pixel_qa');
      // Bits 3 and 5 are cloud shadow and cloud, respectively.
      const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 5));
      // Bits 7 and 9 are low and high atmosphere transparency, respectively.
      const cirrus = qa.bitwiseAnd(1 << 9).or(qa.bitwiseAnd(1 << 7));
      // Remove edge pixels that don't have complete SR data.
      const mask2 = image.select('SR_B4').gt(1).unmask(0); // Check for valid SR data
      return image.updateMask(cloud.not()).updateMask(cirrus.not()).updateMask(mask2);
    };

    // Function to calculate MNDWI for Landsat 5/7
    const addMNDWIL457 = function(image) {
      return image.addBands(image.normalizedDifference(['B2', 'B5']).rename('MNDWI'));
    };

    // Function to calculate MNDWI for Landsat 8
    const addMNDWIL8 = function(image) {
      return image.addBands(image.normalizedDifference(['B3', 'B6']).rename('MNDWI'));
    };

    // Function to calculate land area
    const calculateLandArea = function(imageCollection, year) {
      let image = null;
      let bandNames = [];
      let cloudMaskFn = null;
      let mndwiFn = null;

      if (year === 1999) {
        image = imageCollection.select(['B2', 'B5', 'pixel_qa']);
        cloudMaskFn = cloudMaskL457;
        mndwiFn = addMNDWIL457;
      } else { // 2019
        image = imageCollection.select(['B3', 'B6', 'pixel_qa']);
        cloudMaskFn = cloudMaskL8;
        mndwiFn = addMNDWIL8;
      }

      // Apply cloud mask and add MNDWI
      const processedCollection = image.map(cloudMaskFn).map(mndwiFn);

      const medianImage = processedCollection.median();

      // Check for empty collection
      if (imageCollection.size().getInfo() === 0) {
        return { area: null, count: 0, images: 0 };
      }

      if (medianImage.bandNames().getInfo().indexOf('MNDWI') === -1) {
          throw new Error('MNDWI band not found after processing.');
      }

      // Threshold MNDWI to classify land (MNDWI > 0 for land, Adjust as needed)
      const landMask = medianImage.select('MNDWI').gt(0.1); // Slightly higher threshold for better water separation

      // Calculate pixel area
      const landAreaImage = landMask.multiply(ee.Image.pixelArea()).divide(1000000); // Area in sq km

      // Reduce region to get sum of land area
      const result = landAreaImage.reduceRegion({
        reducer: ee.Reducer.sum().unweighted(), // Unweighted sum
        geometry: geometry,
        scale: 30, // Landsat resolution
        maxPixels: 1e9,
      });

      const landAreaSqKm = result.get('MNDWI').getInfo();

      // Count valid pixels after masking
      const validPixelsCount = medianImage.select('MNDWI')
        .reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: geometry,
          scale: 30,
          maxPixels: 1e9,
        }).get('MNDWI').getInfo();

      return { area: landAreaSqKm, count: validPixelsCount, images: imageCollection.size().getInfo() };
    };

    // 2. Data Acquisition & Check for 1999 (Landsat 5)
    let collection1999 = ee.ImageCollection('LANDSAT/LT05/C01/T1_SR')
      .filterBounds(geometry)
      .filterDate(year1_start, year1_end);

    let stats1999 = calculateLandArea(collection1999, 1999);

    if (stats1999.images === 0) {
      // Fallback to Landsat 7 for 1999 if L5 has no images.
      collection1999 = ee.ImageCollection('LANDSAT/LE07/C01/T1_SR')
        .filterBounds(geometry)
        .filterDate(year1_start, year1_end);
      stats1999 = calculateLandArea(collection1999, 1999);
      if (stats1999.images === 0) {
          console.log("No data for 1999 (Landsat 5 or 7).");
          console.log("C1");
          return;
      }
    }

    // 2. Data Acquisition & Check for 2019 (Landsat 8)
    let collection2019 = ee.ImageCollection('LANDSAT/LC08/C01/T1_SR')
      .filterBounds(geometry)
      .filterDate(year2_start, year2_end);

    let stats2019 = calculateLandArea(collection2019, 2019);

    if (stats2019.images === 0) {
      console.log("No data for 2019 (Landsat 8).");
      console.log("C1");
      return;
    }

    // 3. Validation
    if (stats1999.count === 0 || stats2019.count === 0) {
      console.log(`1999 Images: ${stats1999.images}, Valid Pixels: ${stats1999.count}`);
      console.log(`2019 Images: ${stats2019.images}, Valid Pixels: ${stats2019.count}`);
      console.log("C2"); // No valid pixels after masking
      return;
    }

    if (stats1999.area === null || isNaN(stats1999.area) || stats2019.area === null || isNaN(stats2019.area)) {
      console.log(`1999 Area: ${stats1999.area}, 2019 Area: ${stats2019.area}`);
      console.log("C3"); // Calculation failed
      return;
    }

    // 4. Comparison & Final Answer
    console.log(`1999 Images: ${stats1999.images}, Valid Pixels: ${stats1999.count}, Land Area: ${stats1999.area.toFixed(3)} sq km`);
    console.log(`2019 Images: ${stats2019.images}, Valid Pixels: ${stats2019.count}, Land Area: ${stats2019.area.toFixed(3)} sq km`);

    if (stats2019.area < stats1999.area) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (error) {
    console.error("An error occurred:", error.message);
    console.log("D"); // General error or memory issue
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
